htmlPreview.css:
body{margin:0;font:13px/1.4 system-ui,sans-serif;color:#1f2430;background:#f6f5f2}
.app{display:grid;height:100vh}
.side{background:#262a36;color:#cfd3dd;padding:16px 12px;display:flex;flex-direction:column;gap:6px}
.side b{color:#fff;font-size:14px;margin-bottom:10px}
.side span{padding:6px 10px;border-radius:8px}
.side span.on{background:#3b4152;color:#fff}
.top{background:#fff;border-bottom:1px solid #e3e1db;padding:10px 18px;display:flex;gap:18px;align-items:center}
.top b{margin-right:12px}
.top span.on{color:#5b4bdb;font-weight:600}
main{padding:18px;display:grid;gap:12px;align-content:start}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.card{background:#fff;border:1px solid #e3e1db;border-radius:12px;padding:12px}
.card small{color:#7a7f8c;display:block}
.card strong{font-size:20px}
.chart{background:#fff;border:1px solid #e3e1db;border-radius:12px;height:150px;padding:12px;display:flex;align-items:flex-end;gap:8px}
.chart i{flex:1;background:#8c80f0;border-radius:4px 4px 0 0;display:block}
.list{background:#fff;border:1px solid #e3e1db;border-radius:12px}
.list p{margin:0;padding:10px 12px;border-bottom:1px solid #eeece6}
.rail{display:grid;grid-template-columns:1fr 280px;gap:12px}

